class A:
    def saludo(self):
        return "soy A"

class B(A):
    def saludo(self):
        return "soy B"

print(B().saludo())

class A:
    def __init__(self, x):
        self.x = x

class B(A):
    def __init__(self, x, y):
        super().__init__(x)
        self.y = y

b = B(1, 2)
print(b.x + b.y)

class D:
    def __init__(self, v):
        self.v = v

    def __lt__(self, o):
        return self.v < o.v

    def __repr__(self):
        return f"D({self.v})"

print(sorted([D(3), D(1), D(2)]))

class Cuenta:
    def retirar(self, m):
        return f"retiro {m}"

class Ahorros(Cuenta):
    def retirar(self, m):
        if m > 100:
            return "tope excedido"
        return super().retirar(m)

print(Ahorros().retirar(50))
